package stowage

import "sync"

// compartment 是舱位的内部记录。
type compartment struct {
	id        string
	maxWeight int64
	cargo     map[string]*cargo
}

// cargo 是货物的内部记录。
type cargo struct {
	id            string
	weight        int64
	destination   string
	allowMixed    bool
	compartmentID string // 空字符串表示未装载
}

// Registry 是舱单与配载的本地登记处。
//
// Registry 的所有方法都可以安全地并发调用。
type Registry struct {
	mu           sync.Mutex
	compartments map[string]*compartment
	cargos       map[string]*cargo
	adjustments  map[string]*AdjustmentResult // 已成功调整的编号 -> 保存的结果快照
	contents     map[string]string            // 已成功调整的编号 -> 规范化内容键
}

// NewRegistry 创建一个空的登记处。
func NewRegistry() *Registry {
	return &Registry{
		compartments: make(map[string]*compartment),
		cargos:       make(map[string]*cargo),
		adjustments:  make(map[string]*AdjustmentResult),
		contents:     make(map[string]string),
	}
}

// RegisterCompartment 登记一个舱位。
// 编号去掉首尾空白后不得为空，maxWeight 必须为正整数（千克）。
// 编号按去空白后的值识别并区分大小写；重复登记保留原记录。
func (r *Registry) RegisterCompartment(id string, maxWeight int64) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	cid := trimID(id)
	if cid == "" {
		return fail(ErrInvalidID, "", "舱位编号为空")
	}
	if maxWeight <= 0 {
		return fail(ErrInvalidWeight, cid, "舱位 %s 最大承重必须为正整数千克，当前为 %d", cid, maxWeight)
	}
	if _, exists := r.compartments[cid]; exists {
		return fail(ErrAlreadyExists, cid, "舱位 %s 已存在", cid)
	}
	r.compartments[cid] = &compartment{
		id:        cid,
		maxWeight: maxWeight,
		cargo:     make(map[string]*cargo),
	}
	return nil
}

// RegisterCargo 登记一件货物。
// 编号与目的地去掉首尾空白后不得为空，weight 必须为正整数（千克）。
// 货物登记后处于未装载状态。
// 编号按去空白后的值识别并区分大小写；重复登记保留原记录。
func (r *Registry) RegisterCargo(id string, weight int64, destination string, allowMixed bool) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	cid := trimID(id)
	if cid == "" {
		return fail(ErrInvalidID, "", "货物编号为空")
	}
	if weight <= 0 {
		return fail(ErrInvalidWeight, cid, "货物 %s 重量必须为正整数千克，当前为 %d", cid, weight)
	}
	dest := trimID(destination)
	if dest == "" {
		return fail(ErrInvalidDestination, cid, "货物 %s 目的地为空", cid)
	}
	if _, exists := r.cargos[cid]; exists {
		return fail(ErrAlreadyExists, cid, "货物 %s 已存在", cid)
	}
	r.cargos[cid] = &cargo{
		id:          cid,
		weight:      weight,
		destination: dest,
		allowMixed:  allowMixed,
	}
	return nil
}

// Compartment 查询舱位的承重、已用重量、剩余重量与货物清单。
// 编号去掉首尾空白后识别；不存在时返回错误。
func (r *Registry) Compartment(id string) (*CompartmentView, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	cid := trimID(id)
	if cid == "" {
		return nil, fail(ErrInvalidID, "", "舱位编号为空")
	}
	comp, ok := r.compartments[cid]
	if !ok {
		return nil, fail(ErrNotFound, cid, "舱位 %s 不存在", cid)
	}
	view := compartmentView(comp)
	return &view, nil
}

// Cargo 查询货物的当前舱位或未装载状态。
// 编号去掉首尾空白后识别；不存在时返回错误。
func (r *Registry) Cargo(id string) (*CargoView, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	cid := trimID(id)
	if cid == "" {
		return nil, fail(ErrInvalidID, "", "货物编号为空")
	}
	c, ok := r.cargos[cid]
	if !ok {
		return nil, fail(ErrNotFound, cid, "货物 %s 不存在", cid)
	}
	return cargoView(c), nil
}

// cloneResult 复制一份调整结果，避免调用方修改影响已保存的快照。
func cloneResult(r *AdjustmentResult) *AdjustmentResult {
	return &AdjustmentResult{
		ID:                 r.ID,
		CargoChanges:       append([]CargoChange(nil), r.CargoChanges...),
		CompartmentChanges: append([]CompartmentChange(nil), r.CompartmentChanges...),
	}
}

package stowage

import (
	"sort"
)

// cargoView 构造货物快照，重量、目的地与混装许可取登记资料（调用方持锁）。
func cargoView(c *cargo) *CargoView {
	return &CargoView{
		ID:            c.id,
		Weight:        c.weight,
		Destination:   c.destination,
		AllowMixed:    c.allowMixed,
		Loaded:        c.compartmentID != "",
		CompartmentID: c.compartmentID,
	}
}

// compartmentSnapshot 按给定货物集合生成舱位配载快照，是查询实际配载与
// 预览预计配载共用的组装入口：清单按货物编号字典序排列，包含集合中的
// 全部货物；每件货物的重量、目的地与混装许可取登记资料。
//
// projected 为 false 时清单保留货物的真实装载状态与所属舱位（实际配载）；
// 为 true 时一律显示为已装载且属于该舱位（预计配载）。重量合计溢出
// int64 时，已用与剩余重量不提供数值（保持零值），货物清单照常返回。
// 调用方持锁。
func compartmentSnapshot(comp *compartment, set map[string]*cargo, projected bool) CompartmentView {
	ids := make([]string, 0, len(set))
	for cid := range set {
		ids = append(ids, cid)
	}
	sort.Strings(ids)
	views := make([]CargoView, 0, len(ids))
	for _, cid := range ids {
		c := set[cid]
		view := *cargoView(c)
		if projected {
			// 预计清单中的货物按模拟配载完成后的所属舱位展示；cargoView
			// 返回的是值副本，改写位置字段不影响登记处。
			view.Loaded = true
			view.CompartmentID = comp.id
		}
		views = append(views, view)
	}
	view := CompartmentView{
		ID:        comp.id,
		MaxWeight: comp.maxWeight,
		Cargo:     views,
	}
	// 重量合计规则与配载校验共用同一入口；溢出时已用与剩余重量保持零值。
	if used, ok := weightTotal(set); ok {
		view.UsedWeight = used
		view.RemainingWeight = comp.maxWeight - used
	}
	return view
}

// compartmentView 生成舱位当前实际配载的快照（调用方持锁）。
func compartmentView(comp *compartment) CompartmentView {
	return compartmentSnapshot(comp, comp.cargo, false)
}

// compartmentAfterView 生成舱位在模拟配载下的预计快照（调用方持锁）。
func compartmentAfterView(comp *compartment, set map[string]*cargo) CompartmentView {
	return compartmentSnapshot(comp, set, true)
}

// OpKind 表示调整操作的种类。
type OpKind int

const (
	// OpLoad 装载：将未装载的货物装入目标舱位。
	OpLoad OpKind = iota
	// OpUnload 卸下：将已装载的货物从当前舱位移除，货物记录保留。
	OpUnload
	// OpMove 移动：将已装载的货物直接改放到目标舱位。
	OpMove
)

// String 返回操作种类名称。
func (k OpKind) String() string {
	switch k {
	case OpLoad:
		return "装载"
	case OpUnload:
		return "卸下"
	case OpMove:
		return "移动"
	default:
		return "未知"
	}
}

// Op 是一次调整中的单个操作。
type Op struct {
	Kind    OpKind
	CargoID string
	Target  string // 装载/移动时的目标舱位；卸下时忽略
}

// CargoChange 记录一件货物调整前后的所属舱位。
type CargoChange struct {
	CargoID string
	From    string // 空字符串表示未装载
	To      string // 空字符串表示未装载
}

// CompartmentChange 记录一个舱位调整前后的总重量。
type CompartmentChange struct {
	CompartmentID string
	WeightBefore  int64
	WeightAfter   int64
}

// AdjustmentResult 是一次成功调整的结果快照。
type AdjustmentResult struct {
	ID                 string
	CargoChanges       []CargoChange
	CompartmentChanges []CompartmentChange
}

// CargoView 是货物信息的独立快照。
type CargoView struct {
	ID            string
	Weight        int64
	Destination   string
	AllowMixed    bool
	Loaded        bool
	CompartmentID string // 空字符串表示未装载
}

// CompartmentView 是舱位信息的独立快照。
type CompartmentView struct {
	ID              string
	MaxWeight       int64
	UsedWeight      int64
	RemainingWeight int64
	Cargo           []CargoView // 按编号字典序排列
}

// MixedDestination 描述预计配载中一个舱位内某个目的地对应的全部货物。
type MixedDestination struct {
	Destination string
	CargoIDs    []string // 按编号字典序排列
}

// Rejection 描述预计配载中单个舱位的一条拒绝原因。
//
// Kind 为 ErrOverweight 时，UsedWeight、RemainingWeight、Overweight 与
// MaxWeight 均有效；Kind 为 ErrOverflow（重量溢出）时，预计已用重量、
// 剩余重量与超出量无法用 int64 表示，对应数值字段保持零值，仅提供
// MaxWeight、货物清单与混装原因；Kind 为 ErrMixedLoading 时，
// Destinations 给出各目的地对应的货物，OffendingCargo 列出其中全部
// 不允许混装的货物编号。
type Rejection struct {
	CompartmentID   string
	Kind            ErrorKind
	MaxWeight       int64
	UsedWeight      int64              // 超重时为预计总重量；溢出或混装时为零值
	RemainingWeight int64              // 超重时为预计剩余重量（负值）；其余为零值
	Overweight      int64              // 超重时为超出承重的千克数；其余为零值
	Destinations    []MixedDestination // 混装冲突时各目的地及其货物，按目的地字典序排列
	OffendingCargo  []string           // 混装冲突时全部不允许混装的货物编号，字典序排列
}

// CompartmentPreview 是受影响舱位调整前后的完整配载快照。
// Before 反映调整前配载，清单中的货物保持原所属舱位；After 反映预计
// 配载，清单中的货物一律显示为已装载且属于该舱位，编号、重量、目的地
// 与混装许可仍取登记资料。预计超重时 RemainingWeight 为负值；预计重量
// 溢出 int64 时 After 不提供已用与剩余重量数值（保持零值），货物清单
// 照常返回。
type CompartmentPreview struct {
	ID     string
	Before CompartmentView
	After  CompartmentView
}

// PreviewResult 是一次预览的完整结果，本身是与登记处状态无关的独立快照。
type PreviewResult struct {
	// Submittable 表示按当前登记处状态，这组操作能否作为一次调整提交。
	Submittable bool
	// CargoChanges 列出清单涉及货物的原舱位与预计舱位，按货物编号字典序排列；
	// 未装载用空编号表示。
	CargoChanges []CargoChange
	// Compartments 列出全部受影响舱位调整前后的完整货物清单、已用重量与
	// 剩余重量，按舱位编号字典序排列。即使交换后总重量不变也会列出。
	Compartments []CompartmentPreview
	// Rejections 列出预计配载的全部拒绝原因，按舱位编号排列，同一舱位
	// 先重量（超重/溢出）后混装。为空表示 Submittable 为 true。
	Rejections []Rejection
}

package stowage_test

import (
	"errors"
	"fmt"

	"github.com/descikazuyq/cargo-stowage/stowage"
)

// 本文件为正式提交（Adjust）的结果读法与重复提交提供可运行示例：
// 同一调整编号首次成功后，以原内容再次提交会原样返回首次保存的变化
// 记录，却不会再次装卸；什么算“原内容”（编号去空白且区分大小写、
// 操作顺序无关、卸下目标不参与比较）；同一编号换成不同内容会得到
// “调整编号冲突”的结构化错误；第一次就失败的调整不占用编号，修正
// 后可沿用同一编号。

// newAdjustExampleRegistry 新建空登记处并登记：舱位 C1 承重 100 千克，
// 货物 G1 重 30 千克、目的地上海。每个示例都从这里独立开始，不依赖
// 其他示例留下的状态。
func newAdjustExampleRegistry() *stowage.Registry {
	reg := stowage.NewRegistry()
	must := func(err error) {
		if err != nil {
			panic(err)
		}
	}
	must(reg.RegisterCompartment("C1", 100))
	must(reg.RegisterCargo("G1", 30, "上海", false))
	return reg
}

// orUnloaded 把空舱位编号显示为“（未装载）”。
func orUnloaded(id string) string {
	if id == "" {
		return "（未装载）"
	}
	return id
}

// printResult 打印一次成功调整保存的变化记录：每件货物的原舱位与新舱位，
// 以及每个受影响舱位调整前后的总重量。
func printResult(res *stowage.AdjustmentResult) {
	fmt.Println("调整编号:", res.ID)
	for _, ch := range res.CargoChanges {
		fmt.Printf("货物 %s: %s -> %s\n",
			ch.CargoID, orUnloaded(ch.From), orUnloaded(ch.To))
	}
	for _, cp := range res.CompartmentChanges {
		fmt.Printf("舱位 %s 重量: %d -> %d 千克\n",
			cp.CompartmentID, cp.WeightBefore, cp.WeightAfter)
	}
}

// printCurrent 按当前登记处状态查询 G1 与 C1：货物现在的位置，以及舱位
// 现在的已用重量与剩余重量。它反映的是查询当刻的配载，不是任何历史调整。
func printCurrent(reg *stowage.Registry) {
	g1, err := reg.Cargo("G1")
	if err != nil {
		panic(err)
	}
	fmt.Printf("当前 G1: %s\n", orUnloaded(g1.CompartmentID))
	c1, err := reg.Compartment("C1")
	if err != nil {
		panic(err)
	}
	fmt.Printf("当前 C1: 已用 %d 千克、剩余 %d 千克\n",
		c1.UsedWeight, c1.RemainingWeight)
}

// 主示例：第一次调整 load-g1 把 G1 装入 C1；另一个调整 unload-g1 把它
// 卸下。随后按第一次的编号 load-g1 和原内容（装载 G1 到 C1）再次提交：
// 返回的仍是第一次成功时保存的变化（未装载 -> C1、0 -> 30 千克），
// 但这次提交不会重新装货——重新查询，G1 仍未装载，C1 已用 0 千克。
func Example_adjustResubmitSameContent() {
	reg := newAdjustExampleRegistry()

	// 第一次调整：装载。
	loadOps := []stowage.Op{{Kind: stowage.OpLoad, CargoID: "G1", Target: "C1"}}
	first, err := reg.Adjust("load-g1", loadOps)
	if err != nil {
		panic(err)
	}
	fmt.Println("== 第一次提交 load-g1 的结果 ==")
	printResult(first)

	// 另一次调整（另一个编号）：卸下。
	if _, err := reg.Adjust("unload-g1", []stowage.Op{
		{Kind: stowage.OpUnload, CargoID: "G1"},
	}); err != nil {
		panic(err)
	}
	fmt.Println("== 卸下后的查询 ==")
	printCurrent(reg)

	// 按第一次的编号和原内容再次提交装载。
	again, err := reg.Adjust("load-g1", loadOps)
	if err != nil {
		panic(err)
	}
	fmt.Println("== 再次提交 load-g1 返回的结果 ==")
	printResult(again)

	// 返回的是首次保存的历史记录，不是刚刚发生的变化：当前配载没有被改动。
	fmt.Println("== 再次提交后的查询 ==")
	printCurrent(reg)

	// Output:
	// == 第一次提交 load-g1 的结果 ==
	// 调整编号: load-g1
	// 货物 G1: （未装载） -> C1
	// 舱位 C1 重量: 0 -> 30 千克
	// == 卸下后的查询 ==
	// 当前 G1: （未装载）
	// 当前 C1: 已用 0 千克、剩余 100 千克
	// == 再次提交 load-g1 返回的结果 ==
	// 调整编号: load-g1
	// 货物 G1: （未装载） -> C1
	// 舱位 C1 重量: 0 -> 30 千克
	// == 再次提交后的查询 ==
	// 当前 G1: （未装载）
	// 当前 C1: 已用 0 千克、剩余 100 千克
}

// 什么算“原内容”：调整编号去掉首尾空白后比较；同一批操作只看集合、
// 排列顺序不影响判断；卸下操作填写的目标值不参与比较（执行卸下时本来
// 就忽略它）。下面的再次提交都被识别为原调整，返回同一份首次结果，
// 且都不再次改变配载。
func Example_adjustResubmitEquivalentContent() {
	reg := stowage.NewRegistry()
	must := func(err error) {
		if err != nil {
			panic(err)
		}
	}
	must(reg.RegisterCompartment("C1", 100))
	must(reg.RegisterCargo("G1", 30, "上海", false))
	must(reg.RegisterCargo("G2", 20, "上海", false))

	// 首次成功：一批两条装载，编号带首尾空白提交，保存为 batch-1。
	first, err := reg.Adjust("  batch-1  ", []stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "G1", Target: "C1"},
		{Kind: stowage.OpLoad, CargoID: "G2", Target: "C1"},
	})
	if err != nil {
		panic(err)
	}

	// 另一次调整把两件都卸下，使当前配载与首次成功时不同。
	if _, err := reg.Adjust("unload-all", []stowage.Op{
		{Kind: stowage.OpUnload, CargoID: "G1"},
		{Kind: stowage.OpUnload, CargoID: "G2"},
	}); err != nil {
		panic(err)
	}

	// 再次提交一：编号重排空白、操作顺序倒置，仍识别为 batch-1。
	reversed, err := reg.Adjust("\tbatch-1\t", []stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "G2", Target: "C1"},
		{Kind: stowage.OpLoad, CargoID: "G1", Target: "C1"},
	})
	if err != nil {
		panic(err)
	}

	// 再次提交二：卸下操作即使填了目标（哪怕是不存在的舱位）也不参与
	// 比较，unload-all 同样只回放首次结果。
	unloadAgain, err := reg.Adjust("unload-all", []stowage.Op{
		{Kind: stowage.OpUnload, CargoID: "G2", Target: "CX-随便填"},
		{Kind: stowage.OpUnload, CargoID: "G1", Target: "C1"},
	})
	if err != nil {
		panic(err)
	}

	fmt.Println("首次结果：")
	printResult(first)
	fmt.Println("逆序再次提交结果：")
	printResult(reversed)
	fmt.Println("卸下带目标再次提交，编号:", unloadAgain.ID)
	for _, ch := range unloadAgain.CargoChanges {
		fmt.Printf("货物 %s: %s -> %s\n",
			ch.CargoID, orUnloaded(ch.From), orUnloaded(ch.To))
	}
	// 两次再次提交都没有重新装卸：两件货物仍未装载，C1 已用 0 千克。
	for _, id := range []string{"G1", "G2"} {
		c, _ := reg.Cargo(id)
		fmt.Printf("当前 %s: %s\n", id, orUnloaded(c.CompartmentID))
	}
	c1, _ := reg.Compartment("C1")
	fmt.Printf("当前 C1: 已用 %d 千克、剩余 %d 千克\n",
		c1.UsedWeight, c1.RemainingWeight)

	// Output:
	// 首次结果：
	// 调整编号: batch-1
	// 货物 G1: （未装载） -> C1
	// 货物 G2: （未装载） -> C1
	// 舱位 C1 重量: 0 -> 50 千克
	// 逆序再次提交结果：
	// 调整编号: batch-1
	// 货物 G1: （未装载） -> C1
	// 货物 G2: （未装载） -> C1
	// 舱位 C1 重量: 0 -> 50 千克
	// 卸下带目标再次提交，编号: unload-all
	// 货物 G1: C1 -> （未装载）
	// 货物 G2: C1 -> （未装载）
	// 当前 G1: （未装载）
	// 当前 G2: （未装载）
	// 当前 C1: 已用 0 千克、剩余 100 千克
}

// 调整编号去掉首尾空白后逐字符比较，并且区分大小写：load-g1 与
// Load-G1 是两个互不相干的编号。在货物已被卸下后用大小写不同的编号
// 提交，登记处把它当作一次全新调整——它会真的再装一次货；想取回首次
// 结果，只能逐字符使用原编号。
func Example_adjustResubmitCaseSensitiveID() {
	reg := newAdjustExampleRegistry()

	// load-g1 首次成功：G1 装入 C1，随后另一次调整卸下。
	if _, err := reg.Adjust("load-g1", []stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "G1", Target: "C1"},
	}); err != nil {
		panic(err)
	}
	if _, err := reg.Adjust("unload-g1", []stowage.Op{
		{Kind: stowage.OpUnload, CargoID: "G1"},
	}); err != nil {
		panic(err)
	}

	// 大小写不同的 Load-G1 是全新编号，按当前状态执行，真正装货。
	fresh, err := reg.Adjust("Load-G1", []stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "G1", Target: "C1"},
	})
	if err != nil {
		panic(err)
	}
	fmt.Println("新编号调整：")
	printResult(fresh)
	printCurrent(reg)

	// 而原编号 load-g1 此时再次提交仍只回放首次结果，不会二次装载。
	again, err := reg.Adjust("load-g1", []stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "G1", Target: "C1"},
	})
	if err != nil {
		panic(err)
	}
	fmt.Println("原编号回放编号:", again.ID)
	printCurrent(reg)

	// Output:
	// 新编号调整：
	// 调整编号: Load-G1
	// 货物 G1: （未装载） -> C1
	// 舱位 C1 重量: 0 -> 30 千克
	// 当前 G1: C1
	// 当前 C1: 已用 30 千克、剩余 70 千克
	// 原编号回放编号: load-g1
	// 当前 G1: C1
	// 当前 C1: 已用 30 千克、剩余 70 千克
}

// 同一编号换成不同内容会被拒绝：错误 Kind 为 ErrAdjustmentIDConflict，
// AdjustmentID 指出冲突的调整编号，Error() 给出可直接阅读的中文说明；
// 当前配载保持不变。另一批安排应当另用一个新编号。
func Example_adjustIDConflict() {
	reg := newAdjustExampleRegistry()

	// 编号 load-g1 已成功用于“装载 G1 到 C1”。
	if _, err := reg.Adjust("load-g1", []stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "G1", Target: "C1"},
	}); err != nil {
		panic(err)
	}

	// 同一编号提交不同内容（这里改成卸下）：冲突，不返回任何结果。
	res, err := reg.Adjust("load-g1", []stowage.Op{
		{Kind: stowage.OpUnload, CargoID: "G1"},
	})
	fmt.Println("冲突时有结果返回:", res != nil)
	var serr *stowage.Error
	if errors.As(err, &serr) {
		fmt.Println("拒绝原因:", serr.Kind)
		fmt.Println("调整编号:", serr.AdjustmentID)
		fmt.Println("说明:", serr)
	}

	// G1 仍在 C1，舱位仍是 30/100 千克——冲突提交没有生效。
	printCurrent(reg)

	// 另一批安排另用编号即可正常提交。
	if _, err := reg.Adjust("unload-g1-v2", []stowage.Op{
		{Kind: stowage.OpUnload, CargoID: "G1"},
	}); err != nil {
		panic(err)
	}
	fmt.Println("新编号提交后：")
	printCurrent(reg)

	// Output:
	// 冲突时有结果返回: false
	// 拒绝原因: 调整编号冲突
	// 调整编号: load-g1
	// 说明: 调整编号 load-g1 已用于不同内容
	// 当前 G1: C1
	// 当前 C1: 已用 30 千克、剩余 70 千克
	// 新编号提交后：
	// 当前 G1: （未装载）
	// 当前 C1: 已用 0 千克、剩余 100 千克
}

// 第一次就失败的调整不占用编号：修正安排后沿用同一编号可以成功。
// 这与“已成功调整的重复提交”是两种不同情况——前者编号还没被保存，
// 修正后提交是一次全新生效；后者编号已绑定首次结果，再次提交只会取回
// 那份结果而不会重新执行。
func Example_adjustFailureDoesNotConsumeID() {
	reg := stowage.NewRegistry()
	must := func(err error) {
		if err != nil {
			panic(err)
		}
	}
	// C1 承重只有 20 千克，另有装得下的 C2（100 千克）；G1 重 30 千克。
	must(reg.RegisterCompartment("C1", 20))
	must(reg.RegisterCompartment("C2", 100))
	must(reg.RegisterCargo("G1", 30, "上海", false))

	// 第一次提交 load-g1：装进 C1，30 > 20，超重失败。
	_, err := reg.Adjust("load-g1", []stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "G1", Target: "C1"},
	})
	var serr *stowage.Error
	if errors.As(err, &serr) {
		fmt.Println("第一次原因:", serr.Kind)
		fmt.Println("调整编号:", serr.AdjustmentID)
	}
	g1, _ := reg.Cargo("G1")
	c1, _ := reg.Compartment("C1")
	fmt.Printf("失败后 G1: %s；C1 已用 %d 千克\n",
		orUnloaded(g1.CompartmentID), c1.UsedWeight)

	// 失败不占用编号：目标改成装得下的 C2，沿用同一编号提交即成功。
	res, err := reg.Adjust("load-g1", []stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "G1", Target: "C2"},
	})
	if err != nil {
		panic(err)
	}
	fmt.Println("修正后结果：")
	printResult(res)
	g1, _ = reg.Cargo("G1")
	fmt.Println("修正后 G1 所在舱位:", g1.CompartmentID)

	// Output:
	// 第一次原因: 超重
	// 调整编号: load-g1
	// 失败后 G1: （未装载）；C1 已用 0 千克
	// 修正后结果：
	// 调整编号: load-g1
	// 货物 G1: （未装载） -> C2
	// 舱位 C2 重量: 0 -> 30 千克
	// 修正后 G1 所在舱位: C2
}

package stowage

import (
	"sort"
)

// Preview 预演一批装载、卸下、移动操作，返回这批安排按当前配载完成后的
// 预计结果。
//
// 预览是只读的：无论结果能否提交，货物位置、舱位占用与已成功调整记录
// 都不会改变，也不占用任何调整编号。清单沿用与 Adjust 相同的 Op 表示
// 与编号规则，逐条合法性（货物与舱位是否存在、货物状态、重复操作、
// 移动到原舱位等）与正式提交完全一致：某条操作不合法时，按输入顺序
// 返回第一个非法操作的现有错误，不返回局部预览。
//
// 每条操作本身合法时始终返回完整预览：预计配载违反承重或混装限制时
// Submittable 为 false，并在 Rejections 中一次列全全部受影响舱位的
// 拒绝原因；判断以整批操作完成后的最终配载为准，不会因中间步骤暂时
// 超重而拒绝最终合法的交换。
//
// 预览反映调用时刻登记处的一致快照（登记、配载与已成功调整记录取自
// 同一时刻，不会混入并发调整前后的状态）。返回内容是独立快照，调用
// 方修改不影响登记处或之后的预览；状态未变时连续预览同一清单结果
// 一致。正式提交仍以提交时状态重新判断，不能凭旧预览直接放行。
func (r *Registry) Preview(ops []Op) (*PreviewResult, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	if len(ops) == 0 {
		return nil, fail(ErrEmptyAdjustment, "", "预览清单不包含任何操作")
	}

	// 与正式提交共用同一套逐条校验与最终配载模拟；预览不带调整编号。
	vops, final, affected, err := r.prepareOps(ops, fail)
	if err != nil {
		return nil, err
	}

	// 涉及货物的原舱位与预计舱位，按货物编号字典序排列。from/to 取自
	// 与正式生效、模拟落点同一份去向（routeFor），预览与提交逐件对应。
	cargoChanges := make([]CargoChange, 0, len(vops))
	for _, v := range vops {
		cargoChanges = append(cargoChanges, CargoChange{CargoID: v.cargo.id, From: v.rt.from, To: v.rt.to})
	}
	sort.Slice(cargoChanges, func(i, j int) bool {
		return cargoChanges[i].CargoID < cargoChanges[j].CargoID
	})

	// 受影响舱位调整前后的完整配载，按舱位编号字典序排列。交换中总重量
	// 不变的两个舱位同样列出。
	compIDs := make([]string, 0, len(affected))
	for id := range affected {
		compIDs = append(compIDs, id)
	}
	sort.Strings(compIDs)
	compartments := make([]CompartmentPreview, 0, len(compIDs))
	for _, id := range compIDs {
		compartments = append(compartments, CompartmentPreview{
			ID:     id,
			Before: compartmentView(r.compartments[id]),
			After:  compartmentAfterView(r.compartments[id], final[id]),
		})
	}

	// 预计配载的全部拒绝原因，按舱位编号排列、同舱先重量后混装。
	rejs := r.evaluateFinal(final)
	sort.SliceStable(rejs, func(i, j int) bool {
		if rejs[i].CompartmentID != rejs[j].CompartmentID {
			return rejs[i].CompartmentID < rejs[j].CompartmentID
		}
		return rejKindOrder(rejs[i].Kind) < rejKindOrder(rejs[j].Kind)
	})
	rejections := make([]Rejection, 0, len(rejs))
	for _, rej := range rejs {
		rejections = append(rejections, *cloneRejection(rej))
	}

	return &PreviewResult{
		Submittable:  len(rejections) == 0,
		CargoChanges: cargoChanges,
		Compartments: compartments,
		Rejections:   rejections,
	}, nil
}

// cloneRejection 复制拒绝原因中的切片，保证调用方修改不影响其他结果。
func cloneRejection(x *Rejection) *Rejection {
	cp := &Rejection{
		CompartmentID:   x.CompartmentID,
		Kind:            x.Kind,
		MaxWeight:       x.MaxWeight,
		UsedWeight:      x.UsedWeight,
		RemainingWeight: x.RemainingWeight,
		Overweight:      x.Overweight,
	}
	if x.Destinations != nil {
		cp.Destinations = make([]MixedDestination, len(x.Destinations))
		for i, d := range x.Destinations {
			cp.Destinations[i] = MixedDestination{
				Destination: d.Destination,
				CargoIDs:    append([]string(nil), d.CargoIDs...),
			}
		}
	}
	if x.OffendingCargo != nil {
		cp.OffendingCargo = append([]string(nil), x.OffendingCargo...)
	}
	return cp
}

package stowage_test

import (
	"errors"
	"fmt"

	"github.com/descikazuyq/cargo-stowage/stowage"
)

// newSwapRegistry 新建登记处并完成初始配载：两个承重均为 30 千克的舱位，
// 各装入一件 30 千克、目的地相同且不允许混装的货物。每个示例都从这里
// 独立开始，不依赖其他示例留下的状态。
func newSwapRegistry() *stowage.Registry {
	reg := stowage.NewRegistry()
	must := func(err error) {
		if err != nil {
			panic(err)
		}
	}
	must(reg.RegisterCompartment("C1", 30))
	must(reg.RegisterCompartment("C2", 30))
	must(reg.RegisterCargo("G1", 30, "上海", false))
	must(reg.RegisterCargo("G2", 30, "上海", false))
	_, err := reg.Adjust("load-1", []stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "G1", Target: "C1"},
		{Kind: stowage.OpLoad, CargoID: "G2", Target: "C2"},
	})
	must(err)
	return reg
}

// cargoIDs 提取舱位快照中的货物编号清单。
func cargoIDs(v stowage.CompartmentView) []string {
	ids := make([]string, 0, len(v.Cargo))
	for _, c := range v.Cargo {
		ids = append(ids, c.ID)
	}
	return ids
}

// 预览同一批安排中的两件货物互换：两个舱位各自满载，但限制按整批安排
// 完成后的最终配载判断，交换后每个舱位仍恰好在承重内，因此可以提交。
func Example_previewSwap() {
	reg := newSwapRegistry()

	res, err := reg.Preview([]stowage.Op{
		{Kind: stowage.OpMove, CargoID: "G1", Target: "C2"},
		{Kind: stowage.OpMove, CargoID: "G2", Target: "C1"},
	})
	if err != nil {
		panic(err)
	}

	fmt.Println("可提交:", res.Submittable)
	for _, ch := range res.CargoChanges {
		fmt.Printf("货物 %s: %s -> %s\n", ch.CargoID, ch.From, ch.To)
	}
	// 即使交换后总重量不变，两个舱位仍会列出前后的完整货物清单。
	for _, cp := range res.Compartments {
		fmt.Printf("舱位 %s 前: %v（%d/%d 千克）\n",
			cp.ID, cargoIDs(cp.Before), cp.Before.UsedWeight, cp.Before.MaxWeight)
		fmt.Printf("舱位 %s 后: %v（%d/%d 千克）\n",
			cp.ID, cargoIDs(cp.After), cp.After.UsedWeight, cp.After.MaxWeight)
	}
	// 预计清单中的货物位置按交换后的所属舱位解释。
	fmt.Printf("预计清单中 %s 属于舱位 %s\n",
		res.Compartments[0].After.Cargo[0].ID,
		res.Compartments[0].After.Cargo[0].CompartmentID)

	// 预览是只读的：查询当前货物仍看到交换前的位置。
	g1, _ := reg.Cargo("G1")
	fmt.Println("预览后查询 G1 所在舱位:", g1.CompartmentID)

	// Output:
	// 可提交: true
	// 货物 G1: C1 -> C2
	// 货物 G2: C2 -> C1
	// 舱位 C1 前: [G1]（30/30 千克）
	// 舱位 C1 后: [G2]（30/30 千克）
	// 舱位 C2 前: [G2]（30/30 千克）
	// 舱位 C2 后: [G1]（30/30 千克）
	// 预计清单中 G2 属于舱位 C1
	// 预览后查询 G1 所在舱位: C1
}

// 预览一组会被拒绝的安排：向已满载的 C1 装入第三件货物（10 千克、目的地
// 不同、允许混装）。每条操作本身合法，预览照常返回预计清单，但
// Submittable 为 false，且同时列出超重与混装冲突两条拒绝原因。
func Example_previewRejected() {
	reg := newSwapRegistry()
	if err := reg.RegisterCargo("G3", 10, "北京", true); err != nil {
		panic(err)
	}

	res, err := reg.Preview([]stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "G3", Target: "C1"},
	})
	// 操作本身合法，预览调用不失败；不可提交体现在结果里。
	fmt.Println("预览调用出错:", err != nil)
	fmt.Println("可提交:", res.Submittable)
	for _, cp := range res.Compartments {
		fmt.Printf("舱位 %s 后: %v（%d/%d 千克）\n",
			cp.ID, cargoIDs(cp.After), cp.After.UsedWeight, cp.After.MaxWeight)
	}
	for _, rej := range res.Rejections {
		switch rej.Kind {
		case stowage.ErrOverweight:
			fmt.Printf("舱位 %s 超重 %d 千克（%d/%d）\n",
				rej.CompartmentID, rej.Overweight, rej.UsedWeight, rej.MaxWeight)
		case stowage.ErrMixedLoading:
			for _, d := range rej.Destinations {
				fmt.Printf("舱位 %s 目的地 %s: %v\n", rej.CompartmentID, d.Destination, d.CargoIDs)
			}
			fmt.Printf("不允许混装的货物: %v\n", rej.OffendingCargo)
		}
	}

	// 被拒绝的预览同样不改变配载。
	c1, _ := reg.Compartment("C1")
	fmt.Println("预览后 C1 实际货物:", cargoIDs(*c1))

	// Output:
	// 预览调用出错: false
	// 可提交: false
	// 舱位 C1 后: [G1 G3]（40/30 千克）
	// 舱位 C1 超重 10 千克（40/30）
	// 舱位 C1 目的地 上海: [G1]
	// 舱位 C1 目的地 北京: [G3]
	// 不允许混装的货物: [G1]
	// 预览后 C1 实际货物: [G1]
}

// 操作本身不合法（货物编号不存在）时，预览返回结构化错误且没有局部
// 预览，与“操作合法但最终配载不可提交”的拒绝结果不同。
func Example_previewInvalidOp() {
	reg := newSwapRegistry()

	res, err := reg.Preview([]stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "G9", Target: "C1"},
	})
	fmt.Println("有预览结果:", res != nil)
	var serr *stowage.Error
	if errors.As(err, &serr) {
		fmt.Println("错误原因:", serr.Kind)
		fmt.Println("涉及编号:", serr.ID)
	}

	// Output:
	// 有预览结果: false
	// 错误原因: 对象不存在
	// 涉及编号: G9
}

// 预览通过后用同一批操作正式提交：只有 Adjust 成功才应用安排，此后的
// 查询结果与之前的预计配载对应。
func Example_adjustAfterPreview() {
	reg := newSwapRegistry()

	ops := []stowage.Op{
		{Kind: stowage.OpMove, CargoID: "G1", Target: "C2"},
		{Kind: stowage.OpMove, CargoID: "G2", Target: "C1"},
	}
	res, err := reg.Preview(ops)
	if err != nil {
		panic(err)
	}
	fmt.Println("预览可提交:", res.Submittable)

	// 预览本身不改变配载，也不占用调整编号；正式提交才应用安排。
	adj, err := reg.Adjust("swap-1", ops)
	if err != nil {
		panic(err)
	}
	fmt.Println("已提交调整:", adj.ID)
	g1, _ := reg.Cargo("G1")
	g2, _ := reg.Cargo("G2")
	fmt.Println("提交后 G1 所在舱位:", g1.CompartmentID)
	fmt.Println("提交后 G2 所在舱位:", g2.CompartmentID)

	// Output:
	// 预览可提交: true
	// 已提交调整: swap-1
	// 提交后 G1 所在舱位: C2
	// 提交后 G2 所在舱位: C1
}

package stowage_test

import (
	"errors"
	"fmt"

	"github.com/descikazuyq/cargo-stowage/stowage"
)

// newAmendRegistry 新建登记处并完成初始配载：舱位 C1 承重 100 千克，装入
// 两件目的地不同、都允许混装的货物（G1 30 千克去上海、G2 20 千克去北京），
// 已用 50 千克。每个示例都从这里独立开始，不依赖其他示例留下的状态。
func newAmendRegistry() *stowage.Registry {
	reg := stowage.NewRegistry()
	must := func(err error) {
		if err != nil {
			panic(err)
		}
	}
	must(reg.RegisterCompartment("C1", 100))
	must(reg.RegisterCargo("G1", 30, "上海", true))
	must(reg.RegisterCargo("G2", 20, "北京", true))
	_, err := reg.Adjust("load-1", []stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "G1", Target: "C1"},
		{Kind: stowage.OpLoad, CargoID: "G2", Target: "C1"},
	})
	must(err)
	return reg
}

// 更正已装载货物 G2 的三项资料：重量 20 -> 40 千克、目的地 北京 -> 上海
// （与同舱 G1 相同）、同时取消混装许可。三项作为一次整体替换生效，货物
// 编号与所属舱位不变；目的地一致后同舱共载不再要求混装许可。
func Example_amendLoadedCargo() {
	reg := newAmendRegistry()

	show := func(label string) {
		g2, _ := reg.Cargo("G2")
		c1, _ := reg.Compartment("C1")
